import{_ as t}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as i,o as e,af as l}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const q=JSON.parse('{"title":"Vibe Coding 理念","description":"","frontmatter":{},"headers":[],"relativePath":"zh/tech/philosophy/vibe-coding-philosophy.md","filePath":"zh/tech/philosophy/vibe-coding-philosophy.md","lastUpdated":1787044708000}'),n={name:"zh/tech/philosophy/vibe-coding-philosophy.md"};function s(o,a,r,d,h,p){return e(),i("div",null,[...a[0]||(a[0]=[l(`<h1 id="vibe-coding-理念" tabindex="-1">Vibe Coding 理念 <a class="header-anchor" href="#vibe-coding-理念" aria-label="Permalink to &quot;Vibe Coding 理念&quot;">​</a></h1><blockquote><p>学习来源：<a href="https://www.vibevibe.cn/" target="_blank" rel="noreferrer">Vibe Vibe</a> | 原文引用于 Andrej Karpathy (2025)</p></blockquote><h2 id="一、什么是-vibe-coding" tabindex="-1">一、什么是 Vibe Coding <a class="header-anchor" href="#一、什么是-vibe-coding" aria-label="Permalink to &quot;一、什么是 Vibe Coding&quot;">​</a></h2><blockquote><p>&quot;There&#39;s a new kind of coding I call &#39;vibe coding&#39;, where you fully give in to the vibes, embrace exponentials, and forget that the code even exists.&quot; — <strong>Andrej Karpathy</strong>, 2025</p></blockquote><p>Vibe Coding 是 2025 年提出的最有代表性的 <strong>AI 原生构建方式之一</strong>，也是 Collins 词典年度词汇。</p><h2 id="二、核心特征" tabindex="-1">二、核心特征 <a class="header-anchor" href="#二、核心特征" aria-label="Permalink to &quot;二、核心特征&quot;">​</a></h2><p>Vibe Coding 的核心特征：</p><ol><li><strong>用自然语言描述目标与需求</strong>，而不是所有步骤都亲手完成</li><li><strong>让 AI 参与实现、组织和迭代</strong>，你负责验收、判断和调整</li><li><strong>更快把想法变成真实成果</strong>，因为做出东西往往比空想和完美规划更能推动学习</li></ol><p>简单说：<strong>你负责方向、判断和审美，AI 帮你把作品做出来。</strong></p><h2 id="三、vibe-vibe-课程体系" tabindex="-1">三、Vibe Vibe 课程体系 <a class="header-anchor" href="#三、vibe-vibe-课程体系" aria-label="Permalink to &quot;三、Vibe Vibe 课程体系&quot;">​</a></h2><h3 id="_3-1-学习路径总览" tabindex="-1">3.1 学习路径总览 <a class="header-anchor" href="#_3-1-学习路径总览" aria-label="Permalink to &quot;3.1 学习路径总览&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│                  基础篇：从想法到第一个作品               │</span></span>
<span class="line"><span>│  适合：零基础、设计师、产品经理、文科生                  │</span></span>
<span class="line"><span>│  技术栈：HTML/CSS/JS · AI 工具 · Git · 静态部署      │</span></span>
<span class="line"><span>├─────────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│                  进阶篇：从作品到产品                   │</span></span>
<span class="line"><span>│  适合：想了解完整项目交付流程的开发者                    │</span></span>
<span class="line"><span>│  技术栈：Next.js 16 · React · TypeScript · Tailwind  │</span></span>
<span class="line"><span>│          shadcn/ui · Drizzle · PostgreSQL            │</span></span>
<span class="line"><span>└─────────────────────────────────────────────────────┘</span></span></code></pre></div><h3 id="_3-2-基础篇-从想法到第一个作品" tabindex="-1">3.2 基础篇：从想法到第一个作品 <a class="header-anchor" href="#_3-2-基础篇-从想法到第一个作品" aria-label="Permalink to &quot;3.2 基础篇：从想法到第一个作品&quot;">​</a></h3><p><strong>适合人群</strong>：从未写过代码的小白、文科生、设计师、产品经理</p><p><strong>学习目标</strong>：</p><ul><li>理解 AI 创造工作流</li><li>用 AI 做出第一个作品</li><li>掌握 MVP 思维</li></ul><p><strong>内容预览</strong>：</p><ul><li>觉醒：从码农到指挥官的思维转变</li><li>心法：MVP 思维、不加功能的艺术</li><li>技法：提示词工程、PRD 编写</li><li>实战：从 0 到 1 做出你的作品</li><li>进阶：版本控制、部署、安全意识</li></ul><h3 id="_3-3-进阶篇-从作品到产品" tabindex="-1">3.3 进阶篇：从作品到产品 <a class="header-anchor" href="#_3-3-进阶篇-从作品到产品" aria-label="Permalink to &quot;3.3 进阶篇：从作品到产品&quot;">​</a></h3><p><strong>适合人群</strong>：想了解完整项目交付流程的开发者</p><p><strong>学习目标</strong>：</p><ul><li>全栈架构能力</li><li>生产级部署能力</li><li>协作迭代能力</li><li>工程判断力</li></ul><p><strong>内容预览</strong>：</p><ul><li>开发基础：环境搭建 · 开发工具 · AI 调教 · 文档驱动</li><li>界面与数据：UI/UX · 环境变量 · 数据库 · 测试自动化</li><li>部署运维：公网访问 · Git 协作 · CI/CD · 域名 DNS · VPS 部署</li><li>安全增长：SEO · 数据统计 · 用户反馈与产品迭代</li></ul><h2 id="四、核心理念" tabindex="-1">四、核心理念 <a class="header-anchor" href="#四、核心理念" aria-label="Permalink to &quot;四、核心理念&quot;">​</a></h2><h3 id="_4-1-零基础友好" tabindex="-1">4.1 零基础友好 <a class="header-anchor" href="#_4-1-零基础友好" aria-label="Permalink to &quot;4.1 零基础友好&quot;">​</a></h3><p>不需要任何编程经验，从一个<strong>想法开始</strong>，手把手带你把第一个作品真正做出来。</p><h3 id="_4-2-ai-创造工作流" tabindex="-1">4.2 AI 创造工作流 <a class="header-anchor" href="#_4-2-ai-创造工作流" aria-label="Permalink to &quot;4.2 AI 创造工作流&quot;">​</a></h3><p>学会用 AI 帮你：</p><ul><li>梳理想法</li><li>搭原型</li><li>补内容</li><li>改交互</li><li>推上线</li></ul><p>而<strong>不只是</strong>把 AI 当成写代码的工具。</p><h3 id="_4-3-mvp-思维" tabindex="-1">4.3 MVP 思维 <a class="header-anchor" href="#_4-3-mvp-思维" aria-label="Permalink to &quot;4.3 MVP 思维&quot;">​</a></h3><p>掌握&quot;<strong>最小可行产品</strong>&quot;理念：</p><ul><li>用最少的时间验证你的想法</li><li>避免功能蔓延的陷阱</li><li>先把东西做出来，再逐步完善</li></ul><h3 id="_4-4-从作品到产品" tabindex="-1">4.4 从作品到产品 <a class="header-anchor" href="#_4-4-从作品到产品" aria-label="Permalink to &quot;4.4 从作品到产品&quot;">​</a></h3><p>学习路径更自然：</p><ol><li>基础篇先帮你完成<strong>第一个作品</strong></li><li>进阶篇再带你把作品推进成更完整的<strong>产品</strong></li><li>先完成，再完美</li></ol><h3 id="_4-5-安全意识" tabindex="-1">4.5 安全意识 <a class="header-anchor" href="#_4-5-安全意识" aria-label="Permalink to &quot;4.5 安全意识&quot;">​</a></h3><p>从第一天就建立<strong>安全底线意识</strong>：</p><ul><li>学会保护用户数据</li><li>避免常见安全漏洞</li></ul><h3 id="_4-6-渐进式学习" tabindex="-1">4.6 渐进式学习 <a class="header-anchor" href="#_4-6-渐进式学习" aria-label="Permalink to &quot;4.6 渐进式学习&quot;">​</a></h3><p>学习曲线更平滑：</p><ul><li>基础篇 → 完成作品</li><li>进阶篇 → 完善成产品</li></ul><h2 id="五、vibe-coding-vs-传统编程" tabindex="-1">五、Vibe Coding vs 传统编程 <a class="header-anchor" href="#五、vibe-coding-vs-传统编程" aria-label="Permalink to &quot;五、Vibe Coding vs 传统编程&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>传统编程</th><th>Vibe Coding</th></tr></thead><tbody><tr><td>输入</td><td>代码指令</td><td>自然语言描述目标</td></tr><tr><td>迭代方式</td><td>手动写代码调试</td><td>AI 生成 + 人工验收调整</td></tr><tr><td>关注点</td><td>实现细节</td><td>方向、判断、审美</td></tr><tr><td>效率</td><td>取决于编码速度</td><td>取决于需求描述和判断能力</td></tr><tr><td>适用场景</td><td>需要精确控制的底层实现</td><td>快速验证想法、MVP 构建</td></tr></tbody></table><h2 id="六、思维转变" tabindex="-1">六、思维转变 <a class="header-anchor" href="#六、思维转变" aria-label="Permalink to &quot;六、思维转变&quot;">​</a></h2><h3 id="从码农到指挥官的思维转变" tabindex="-1">从码农到指挥官的思维转变 <a class="header-anchor" href="#从码农到指挥官的思维转变" aria-label="Permalink to &quot;从码农到指挥官的思维转变&quot;">​</a></h3><p>传统思维：我需要学会写代码 ↓ Vibe Coding 思维：我需要学会描述需求和验收标准</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>传统模式：</span></span>
<span class="line"><span>想法 → 写代码（苦力活）→ 调试 → 产出</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Vibe Coding 模式：</span></span>
<span class="line"><span>想法 → 描述给 AI → AI 生成 → 验收判断 → 调整 → 产出</span></span></code></pre></div><p>核心转变：</p><ul><li><strong>执行者</strong> → <strong>验收者</strong></li><li><strong>写代码</strong> → <strong>说清楚要什么</strong></li><li><strong>自己实现</strong> → <strong>让 AI 实现，自己把控方向</strong></li></ul><h2 id="七、工具支持" tabindex="-1">七、工具支持 <a class="header-anchor" href="#七、工具支持" aria-label="Permalink to &quot;七、工具支持&quot;">​</a></h2><h3 id="claude-code-全特性速览" tabindex="-1">Claude Code 全特性速览 <a class="header-anchor" href="#claude-code-全特性速览" aria-label="Permalink to &quot;Claude Code 全特性速览&quot;">​</a></h3><p>想全面了解 Claude Code 有哪些能力？访问 <a href="https://cclog.vibevibe.cn" target="_blank" rel="noreferrer">cclog.vibevibe.cn</a> 查看从 v0.2 到 v2.1 的完整功能梳理，涵盖：</p><ul><li><strong>220+ 个版本</strong></li><li><strong>1000+ 项更新</strong></li><li>AI 模型、多 Agent 协作、MCP 生态、终端体验、安全沙箱等核心能力</li></ul><h3 id="在线-ide-skills" tabindex="-1">在线 IDE + Skills <a class="header-anchor" href="#在线-ide-skills" aria-label="Permalink to &quot;在线 IDE + Skills&quot;">​</a></h3><ul><li><strong>云端 IDE</strong>：内置完整 Node.js 24、Python、Docker 等开发环境，无需本地配置</li><li><strong>50+ AI Skills</strong>：预装丰富的 AI 辅助技能包，覆盖开发全流程</li><li><strong>开箱即用</strong>：登录即可开始编程实践，学习门槛最低</li></ul><h2 id="八、适合谁学习" tabindex="-1">八、适合谁学习？ <a class="header-anchor" href="#八、适合谁学习" aria-label="Permalink to &quot;八、适合谁学习？&quot;">​</a></h2><table tabindex="0"><thead><tr><th>人群</th><th>推荐路径</th><th>理由</th></tr></thead><tbody><tr><td>设计师 / 产品经理</td><td>基础篇</td><td>零代码基础也能做出可运行的原型</td></tr><tr><td>文科生 / 跨专业</td><td>基础篇</td><td>从最基础的概念开始，循序渐进</td></tr><tr><td>前端开发者</td><td>进阶篇</td><td>扩展后端能力，成为全栈工程师</td></tr><tr><td>后端开发者</td><td>进阶篇</td><td>了解现代前端生态和 Next.js</td></tr><tr><td>创业者 / 独立开发者</td><td>两者皆可</td><td>快速搭建 MVP，独立完成产品</td></tr><tr><td>想提升效率的开发者</td><td>基础篇 + 进阶篇</td><td>系统学习 AI 辅助开发工作流</td></tr></tbody></table><h2 id="九、课程不只是教你学-ai-编程" tabindex="-1">九、课程不只是教你学 AI 编程 <a class="header-anchor" href="#九、课程不只是教你学-ai-编程" aria-label="Permalink to &quot;九、课程不只是教你学 AI 编程&quot;">​</a></h2><p>这门课不是为了把你一次训练成资深工程师。你不会突然精通算法、框架源码，或者一下获得大厂面试通关能力。</p><p><strong>但你会获得</strong>：</p><ul><li>把想法做成<strong>真实作品的能力</strong></li><li>一套<strong>可重复使用的 AI 协作方法</strong></li><li>更强的<strong>产品判断、迭代习惯和上线信心</strong></li></ul><p>这和传统程序员成长路线不是一回事，但它同样非常有价值，而且更贴近很多普通人真正想解决的问题。</p><h2 id="十、项目资源" tabindex="-1">十、项目资源 <a class="header-anchor" href="#十、项目资源" aria-label="Permalink to &quot;十、项目资源&quot;">​</a></h2><ul><li><strong>GitHub 仓库</strong>：<a href="https://github.com/datawhalechina/vibe-vibe" target="_blank" rel="noreferrer">datawhalechina/vibe-vibe</a></li><li><strong>在线 IDE</strong>：云端开发环境，无需安装任何软件</li><li><strong>部署指南</strong>：支持私有化部署</li></ul>`,66)])])}const v=t(n,[["render",s]]);export{q as __pageData,v as default};
